float RangeRemapValue ( float value, float inLow, float inHigh, float outLow, float outHigh ) {
	return outLow + ( value - inLow ) * ( outHigh - outLow ) / ( inHigh - inLow );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    vec2 centerPos = vec2( iTime );

    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = ( fragCoord / iResolution.xy - vec2( 0.5f ) ) + centerPos;
    vec3 col = vec3( 0.0f );

    if ( uv.x - centerPos.x < 0.0f ) { // remapping the UV in something like the style of Cadia's Walrus
        // (https://www.caida.org/catalog/software/walrus/gallery1/med-gr-l-4.png)
        float offsetLength = length( uv - centerPos );
        vec2 normOffset = normalize( uv - centerPos );
        uv = RangeRemapValue( sqrt( offsetLength ), 0.0f, 1.0f, 0.1f, 1.0f / offsetLength ) * normOffset + centerPos;
    }

    // do a square ish grid with the uv
    // if ( sin( uv.y ) < 0.3f || cos( uv.x ) < 0.3f ) {
    if ( length( floor( uv ) + vec2( 0.5f ) - uv ) < 0.3f ) {
        // col = vec3( max( sin( uv.y ) - 0.3f, cos( uv.x ) - 0.3f ) );
        col = vec3( 1.0f );
    }

    // Output to screen
    fragColor = vec4( col, 1.0f );
}
